package com.gymmind.knowledge.infrastructure.search; import org.springframework.stereotype.Component; import java.util.*; @Component public class InMemoryKeywordIndex implements KeywordIndexPort {private final Map<String,IndexedChunk> data=new HashMap<>(); public void upsert(IndexedChunk c){data.put(c.id(),c);} public List<IndexedChunk> search(String q,Long t){return data.values().stream().filter(c->t.equals(c.tenantId())&&c.text().toLowerCase().contains(q.toLowerCase())).toList();} public void delete(String id,Long t){data.computeIfPresent(id,(k,c)->t.equals(c.tenantId())?null:c);}}
